// Tudo chega como texto (o app manda formulário simples).
const corpo = $('Recebe pedido do app').first().json.body || {};
const texto = (v) => String(v ?? '').trim();
const ACOES = ['listar', 'salvar', 'editar', 'excluir'];
const acao = ACOES.includes(texto(corpo.acao)) ? texto(corpo.acao) : '';
// editar / excluir: o e-mail do cadastro (id).
const id = /^rec[A-Za-z0-9]{14}$/.test(texto(corpo.id)) ? texto(corpo.id) : '';
const email = texto(corpo.email).replace(/\s+/g, '');
// A quem pertence: opcional, texto livre.
const pertence = texto(corpo.pertence).replace(/\s+/g, ' ').slice(0, 120);
const VALIDO = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
let erro = '';
if (!acao) erro = 'Ação inválida.';
else if ((acao === 'editar' || acao === 'excluir') && !id) erro = 'E-mail inválido.';
else if ((acao === 'salvar' || acao === 'editar') && (!VALIDO.test(email) || email.length > 254)) erro = 'Esse e-mail não parece certo. Confira e tente de novo.';
return [{ json: { acao, id, email, pertence, erro } }];

const e = $('Le entrada').first().json;
const ler = (no) => $(no).all().map((i) => i.json);
const brutos = {
  emails: ler('Busca e-mails'), clientes: ler('Busca clientes'), contatos: ler('Busca contatos'),
  administradoras: ler('Busca administradoras'), chamados: ler('Busca chamados'),
};
const recusa = (mensagem) => [{ json: { gravar: false, resposta: { ok: false, mensagem } } }];

// Banco fora do ar não pode parecer "nenhum e-mail".
if (Object.values(brutos).some((lista) => lista.some((j) => j && j.error))) {
  return recusa('Não foi possível falar com o banco agora. Tente de novo em instantes.');
}

const BASE = 'http://127.0.0.1:5690/v0/app6PyYmtFduIMp7B/';
const T = { emails: 'tblEmailsCadast01', clientes: 'tbl5Joji6gAir3mNh', contatos: 'tblXXOEOCwQnC2qFX', administradoras: 'tblAdministrad001' };
const QUEBRA = String.fromCharCode(10);
const VALIDO = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
// Fulano@ e fulano@ são o mesmo e-mail.
const chave = (t) => String(t || '').trim().toLowerCase();
// O financeiro do cliente aceita vírgula e ponto e vírgula também; os outros, um por linha.
const separar = (t) => String(t || '').split(/[\n,;]+/).map((v) => v.trim()).filter(Boolean);
const registros = (lista) => lista.filter((j) => j && j.id);

const cadastro = registros(brutos.emails).map((j) => ({
  id: j.id, email: String((j.fields && j.fields.Email) || '').trim(), pertence: (j.fields && j.fields.Pertence) || '',
}));

// Onde cada e-mail é usado (e de onde sai ou muda ao editar/excluir). Chamados guardam uma
// cópia do contato na hora: entram no cadastro, mas não mudam (são histórico).
const lugares = [];
registros(brutos.clientes).forEach((j) => {
  const f = j.fields || {};
  lugares.push({ tabela: T.clientes, campo: 'Emails_Financeiro_NFE', id: j.id, tipo: 'Cliente',
    nome: f.Nome_Fantasia_Identificador || f.Razao_Social_Nome || 'Cliente sem nome', emails: separar(f.Emails_Financeiro_NFE) });
});
registros(brutos.contatos).forEach((j) => {
  const f = j.fields || {};
  lugares.push({ tabela: T.contatos, campo: 'Emails', id: j.id, tipo: 'Contato', nome: f.Nome_Contato || 'Contato sem nome', emails: separar(f.Emails) });
});
registros(brutos.administradoras).forEach((j) => {
  const f = j.fields || {};
  lugares.push({ tabela: T.administradoras, campo: 'Emails', id: j.id, tipo: 'Administradora', nome: f.Nome || 'Administradora sem nome', emails: separar(f.Emails) });
});
const deChamados = registros(brutos.chamados).flatMap((j) => separar(j.fields && j.fields.Contato_Email));

const usadoEm = (email) => {
  const vistos = new Set();
  return lugares.filter((l) => l.emails.some((m) => chave(m) === chave(email)))
    .map((l) => ({ tipo: l.tipo, nome: l.nome }))
    .filter((u) => !vistos.has(u.tipo + '|' + u.nome) && vistos.add(u.tipo + '|' + u.nome));
};
const ordenar = (lista) => lista.sort((a, b) => a.email.localeCompare(b.email, 'pt-BR', { sensitivity: 'base' }));
const emLotes = (lista) => {
  const lotes = [];
  for (let i = 0; i < lista.length; i += 10) lotes.push(lista.slice(i, i + 10));
  return lotes;
};

if (e.acao === 'listar') {
  // Todo e-mail que aparece nos outros cadastros entra aqui sozinho (sem dono escrito ainda).
  const conhecidos = new Set(cadastro.map((c) => chave(c.email)));
  const novos = [];
  for (const m of [...lugares.flatMap((l) => l.emails), ...deChamados]) {
    if (!VALIDO.test(m) || m.length > 254 || conhecidos.has(chave(m))) continue;
    conhecidos.add(chave(m));
    novos.push(m);
  }
  const lista = ordenar([...cadastro, ...novos.map((m) => ({ id: '', email: m, pertence: '' }))])
    .map((c) => ({ ...c, usadoEm: usadoEm(c.email) }));
  if (!novos.length) return [{ json: { gravar: false, resposta: { ok: true, emails: lista } } }];
  return emLotes(novos).map((lote) => ({ json: {
    gravar: true, acao: 'listar', lista, metodo: 'POST', url: BASE + T.emails,
    corpo: { records: lote.map((m) => ({ fields: { Email: m } })) },
  } }));
}

if (e.acao === 'salvar') {
  const igual = cadastro.find((c) => chave(c.email) === chave(e.email));
  if (igual) {
    return [{ json: { gravar: false, resposta: { ok: false, jaExiste: true, mensagem: 'O e-mail "' + igual.email + '" já está cadastrado.',
      email: { ...igual, usadoEm: usadoEm(igual.email) } } } }];
  }
  return [{ json: { gravar: true, acao: 'salvar', resultado: { id: '', email: e.email, pertence: e.pertence, usadoEm: usadoEm(e.email) },
    metodo: 'POST', url: BASE + T.emails, corpo: { records: [{ fields: { Email: e.email, Pertence: e.pertence } }] } } }];
}

// editar / excluir
const atual = cadastro.find((c) => c.id === e.id);
if (!atual) return recusa('Esse e-mail não está mais no cadastro. Toque em Atualizar.');

// Trocar (editar) ou tirar (excluir) o e-mail em todo lugar onde ele está, sem repetir.
const mexer = (trocarPor) => {
  const porTabela = {};
  for (const l of lugares) {
    if (!l.emails.some((m) => chave(m) === chave(atual.email))) continue;
    const novos = [];
    for (const m of l.emails.map((m) => (chave(m) === chave(atual.email) ? trocarPor : m))) {
      if (m && !novos.some((x) => chave(x) === chave(m))) novos.push(m);
    }
    (porTabela[l.tabela] = porTabela[l.tabela] || []).push({ id: l.id, fields: { [l.campo]: novos.join(QUEBRA) } });
  }
  const itens = [];
  for (const [tabela, lista] of Object.entries(porTabela)) {
    for (const lote of emLotes(lista)) itens.push({ metodo: 'PATCH', url: BASE + tabela, corpo: { records: lote } });
  }
  return itens;
};
const quantos = (n) => (n === 1 ? '1 cadastro' : n + ' cadastros');

if (e.acao === 'editar') {
  const outro = cadastro.find((c) => c.id !== e.id && chave(c.email) === chave(e.email));
  if (outro) return recusa('O e-mail "' + outro.email + '" já está cadastrado.');
  const mudouEmail = atual.email !== e.email;
  const nosLugares = mudouEmail ? mexer(e.email) : [];
  const usos = usadoEm(atual.email).length;
  const resultado = { id: atual.id, email: e.email, pertence: e.pertence, usadoEm: mudouEmail ? usadoEm(atual.email) : usadoEm(e.email) };
  const mensagemOk = mudouEmail && usos ? 'E-mail trocado aqui e em ' + quantos(usos) + '.' : 'Salvo.';
  return [
    { json: { gravar: true, acao: 'editar', resultado, mensagemOk, metodo: 'PATCH', url: BASE + T.emails,
      corpo: { records: [{ id: atual.id, fields: { Email: e.email, Pertence: e.pertence } }] } } },
    ...nosLugares.map((x) => ({ json: { gravar: true, acao: 'editar', ...x } })),
  ];
}

// excluir: sai do cadastro e de todo lugar onde estava.
const usos = usadoEm(atual.email).length;
return [
  { json: { gravar: true, acao: 'excluir', mensagemOk: usos ? 'E-mail excluído e tirado de ' + quantos(usos) + '.' : 'E-mail excluído.',
    metodo: 'DELETE', url: BASE + T.emails + '/' + atual.id, corpo: {} } },
  ...mexer('').map((x) => ({ json: { gravar: true, acao: 'excluir', ...x } })),
];

const d = $('Decide').first().json;
const falha = [{ json: { ok: false, mensagem: 'Não foi possível salvar agora. Tente de novo em instantes.' } }];
const gravados = $input.all().map((i) => i.json);

// listar: os que entraram agora ganham o código que o banco deu.
if (d.acao === 'listar') {
  const ids = new Map();
  gravados.forEach((g) => (g.records || []).forEach((r) => {
    if (r && r.id) ids.set(String((r.fields && r.fields.Email) || '').trim().toLowerCase(), r.id);
  }));
  return [{ json: { ok: true, emails: d.lista.map((c) => (c.id ? c : { ...c, id: ids.get(c.email.trim().toLowerCase()) || '' })) } }];
}
if (d.acao === 'excluir') return [{ json: { ok: true, mensagem: d.mensagemOk } }];
if (d.acao === 'editar') return [{ json: { ok: true, mensagem: d.mensagemOk, email: d.resultado } }];

// salvar
const reg = ((gravados[0] && gravados[0].records) || [])[0];
if (!reg || !reg.id) return falha;
return [{ json: { ok: true, mensagem: 'E-mail cadastrado.', email: { ...d.resultado, id: reg.id } } }];
